CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_finish(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op private.dic_admin_account_delete_operations; removed integer:=0; community_ids uuid[]:='{}'::uuid[];
begin
 select * into op from private.dic_admin_account_delete_operations where id=p_operation_id for update;
 if not found or op.actor_id is distinct from p_actor_id then
  raise exception using errcode='42501',message='Deletion operation unavailable.';
 end if;
 if op.phase='completed' then
  return jsonb_build_object('ok',true,'completed',true,'community_removed',op.community_removed,'retry',true);
 end if;
 if op.phase<>'prepared' then raise exception using errcode='23514',message='Deletion was not prepared.'; end if;
 -- Never trust an edge-reported success alone. The DB verifies Auth is gone.
 if exists(select 1 from auth.users where id=op.target_id) then
  raise exception using errcode='23514',message='Auth account still exists.';
 end if;
 if op.community_mode='remove' then
  -- Capture IDs BEFORE removing their private association; only this member's
  -- immutable contributor IDs may be selected, including detached old shots.
  select coalesce(array_agg(cl.community_shot_id order by cl.community_shot_id),'{}'::uuid[])
    into community_ids from private.contribution_links cl
    where cl.contributor_id=any(op.contributor_ids);
  -- Keep private review audit records but remove public references to purged shots.
  update public.admin_reviews set community_shot_id=null
    where community_shot_id=any(community_ids);
  delete from private.contribution_links where community_shot_id=any(community_ids)
    and contributor_id=any(op.contributor_ids);
  delete from public.community_shots where id=any(community_ids);
  get diagnostics removed=row_count;
  -- Contributor tokens for removed data have no future weighting role.
  delete from private.contributors c where c.id=any(op.contributor_ids)
    and c.owner_id is null and not exists(
      select 1 from private.contribution_links cl where cl.contributor_id=c.id);
 end if;
 update private.dic_admin_account_delete_operations
  set phase='completed',community_removed=removed,completed_at=now(),
      expected_impact=expected_impact-'email'-'member_id',
      contributor_ids='{}'::uuid[] where id=op.id;
 return jsonb_build_object('ok',true,'completed',true,'community_removed',removed);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_prepare(p_operation_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare op private.dic_admin_account_delete_operations; ids uuid[]; actual jsonb; storage_blocked boolean:=false;
begin
 select * into op from private.dic_admin_account_delete_operations
 where id=p_operation_id for update;
 if not found or op.actor_id is distinct from p_actor_id then
  raise exception using errcode='42501',message='Deletion operation unavailable.';
 end if;
 if op.phase='completed' then return jsonb_build_object('ok',true,'completed',true); end if;
 if not exists(select 1 from private.app_admins where owner_id=p_actor_id)
    or not exists(select 1 from private.beta_members
       where owner_id=p_actor_id and enabled and admitted_at is not null) then
  raise exception using errcode='42501',message='Administrator no longer admitted.';
 end if;
 if exists(select 1 from private.app_admins where owner_id=op.target_id)
    or op.target_id=p_actor_id then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 if op.phase='requested' then
  if not exists(select 1 from auth.users where id=op.target_id) then
   raise exception using errcode='23514',message='Target account is missing before preparation.';
  end if;
  -- Recheck the same preview under the service-side record lock.
  -- No JWT actor impersonation or unsafe service-role bypass of an admin check.
  actual:=private.dic_admin_account_delete_impact(op.target_id);
  if actual is distinct from op.expected_impact then
   raise exception using errcode='PT409',message='Account changed after confirmation.';
  end if;
  select coalesce(array_agg(c.id order by c.id),'{}'::uuid[]) into ids
  from private.contributors c where c.owner_id=op.target_id;
  -- Supabase Auth deletion refuses users who own Storage objects. Fail before
  -- changing admission when the live provider exposes that table.
  if to_regclass('storage.objects') is not null then
   execute 'select exists(select 1 from storage.objects where owner=$1 or owner_id=$1::text)'
     into storage_blocked using op.target_id;
   if storage_blocked then
    raise exception using errcode='23514',message='Member has Storage-owned objects; review before deletion.';
   end if;
  end if;
  -- Prevent deletion of prior actor audit evidence if a formerly privileged user
  -- was subsequently demoted. Do not silently erase immutable admin audits.
  if exists(select 1 from private.admin_content_edits where actor_id=op.target_id) then
   raise exception using errcode='23514',message='Historical administrative actor audit requires separate review.';
  end if;
  update private.beta_members set enabled=false where owner_id=op.target_id;
  -- Eliminate restrictive user references; retain minimum action/timestamp audit.
  update private.admin_content_edits
     set subject_owner_id=null,before_values='{}'::jsonb,after_values='{}'::jsonb
     where subject_owner_id=op.target_id;
  delete from private.dic_source_attempts where owner_id=op.target_id;
  update private.import_control
     set owner_only_exception_owner_id=null,owner_only_exception_approved_at=null,
         owner_only_exception_expires_at=null
     where owner_only_exception_owner_id=op.target_id;
  update private.dic_admin_account_delete_operations
     set phase='prepared',contributor_ids=ids,prepared_at=now()
     where id=op.id;
  op.phase:='prepared';op.contributor_ids:=ids;
 end if;
 if op.phase='prepared' and exists(
  select 1 from private.beta_members where owner_id=op.target_id and enabled
 ) then
  raise exception using errcode='23514',message='Admission unexpectedly restored while deleting.';
 end if;
 return jsonb_build_object('ok',true,'target_id',op.target_id,'mode',op.community_mode,'phase',op.phase);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_preview(p_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid();
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_member_id is null or p_member_id=actor or
    exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 return private.dic_admin_account_delete_impact(p_member_id);
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_account_delete_request(p_member_id uuid, p_community_mode text, p_expected_impact jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); actual jsonb; prior private.dic_admin_account_delete_operations; opid uuid;
begin
 perform private.require_member();
 if actor is null or not private.is_admin() then
  raise exception using errcode='42501',message='Administrator required.';
 end if;
 if p_community_mode not in ('keep','remove') or p_community_mode is null
    or p_expected_impact is null or p_member_id is null then
  raise exception using errcode='22023',message='Invalid account deletion confirmation.';
 end if;
 if p_member_id=actor or exists(select 1 from private.app_admins where owner_id=p_member_id) then
  raise exception using errcode='42501',message='Administrator accounts are protected.';
 end if;
 select * into prior from private.dic_admin_account_delete_operations
 where target_id=p_member_id and phase<>'completed' for update;
 if found then
  if prior.actor_id is distinct from actor or prior.community_mode<>p_community_mode then
   raise exception using errcode='23514',message='Another deletion is already in progress.';
  end if;
  return jsonb_build_object('ok',true,'operation_id',prior.id,'phase',prior.phase,'retry',true);
 end if;
 perform 1 from auth.users where id=p_member_id for update;
 actual:=private.dic_admin_account_delete_preview(p_member_id);
 if actual is distinct from p_expected_impact then
  raise exception using errcode='PT409',message='Account records changed. Review deletion impact again.';
 end if;
 insert into private.dic_admin_account_delete_operations(actor_id,target_id,community_mode,expected_impact)
 values(actor,p_member_id,p_community_mode,actual) returning id into opid;
 return jsonb_build_object('ok',true,'operation_id',opid,'phase','requested');
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_coffee_candidates(p_submission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.coffee_submissions;
begin
 perform private.require_member();
 if (select auth.uid()) is null or not private.is_admin() then
   raise exception using errcode='42501',message='Administrator required.';
 end if;
 select * into s from public.coffee_submissions where id=p_submission_id and status in ('pending','conflict');
 if not found then raise exception using errcode='22023',message='Pending submission unavailable.'; end if;
 return jsonb_build_object('candidates',coalesce((
   select jsonb_agg(row_data order by cname, cid)
   from (
     select c.id as cid,c.name as cname,
       jsonb_build_object('id',c.id,'name',c.name,'roaster',c.roaster,
         'release_label',c.release_label,'origin',c.origin,'process',c.process) as row_data
     from public.coffees c
     where c.verification_state='verified' and c.merged_into_id is null
       and private.dic_canonical_roaster_key(c.roaster)=private.dic_canonical_roaster_key(s.proposed_data->>'roaster')
       and (private.dic_coffee_key(c.name)=private.dic_coffee_key(s.proposed_data->>'name')
          or extensions.similarity(private.dic_coffee_key(c.name),
                 private.dic_coffee_key(s.proposed_data->>'name'))>=0.63)
       and (c.release_label is null or nullif(s.proposed_data->>'release_label','') is null
         or private.dic_coffee_key(c.release_label)=private.dic_coffee_key(s.proposed_data->>'release_label'))
       and (c.origin is null or nullif(s.proposed_data->>'origin','') is null
         or private.dic_coffee_key(c.origin)=private.dic_coffee_key(s.proposed_data->>'origin'))
       and (c.process is null or nullif(s.proposed_data->>'process','') is null
         or private.dic_coffee_key(c.process)=private.dic_coffee_key(s.proposed_data->>'process'))
     order by c.name,c.id limit 25
   ) candidates
 ),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION private.dic_admin_delete_preview(p_kind text, p_record_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rev bigint; lib_count bigint:=0; shot_count bigint:=0;
 notes_count bigint:=0; community_count bigint:=0; submissions_count bigint:=0;
 source_count bigint:=0; linked_count bigint:=0; merged_count bigint:=0;
BEGIN
 PERFORM private.require_member();
 IF auth.uid() IS NULL OR NOT private.is_admin() THEN
  RAISE EXCEPTION USING errcode='42501',message='Administrator required.';
 END IF;
 IF p_record_id IS NULL OR p_kind IS NULL OR p_kind NOT IN ('shot','submission','approved') THEN
  RAISE EXCEPTION USING errcode='22023',message='Unsupported delete target.';
 END IF;
 IF p_kind='shot' THEN
  SELECT revision INTO rev FROM public.shots WHERE id=p_record_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='Shot unavailable.'; END IF;
  shot_count:=1;
  SELECT count(*) INTO notes_count FROM public.shot_notes WHERE shot_id=p_record_id;
  SELECT count(*) INTO linked_count FROM private.contribution_links WHERE shot_id=p_record_id;
 ELSIF p_kind='submission' THEN
  SELECT revision INTO rev FROM public.coffee_submissions WHERE id=p_record_id AND status IN ('pending','conflict');
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='Pending submission unavailable.'; END IF;
  submissions_count:=1;
  SELECT count(*) INTO lib_count FROM public.library_entries WHERE submission_id=p_record_id;
  SELECT count(*) INTO shot_count FROM public.shots s JOIN public.library_entries l ON l.id=s.library_entry_id
    WHERE l.submission_id=p_record_id;
  SELECT count(*) INTO notes_count FROM public.shot_notes n JOIN public.shots s ON s.id=n.shot_id
   JOIN public.library_entries l ON l.id=s.library_entry_id WHERE l.submission_id=p_record_id;
  SELECT count(*) INTO linked_count FROM private.dic_coffee_first_entry WHERE first_submission_id=p_record_id;
 ELSE
  SELECT revision INTO rev FROM public.coffees WHERE id=p_record_id AND merged_into_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION USING errcode='22023',message='Canonical coffee unavailable.'; END IF;
  SELECT count(*) INTO submissions_count FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id;
  SELECT count(*) INTO lib_count FROM public.library_entries l
   WHERE l.coffee_id=p_record_id OR l.submission_id IN
    (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  SELECT count(*) INTO shot_count FROM public.shots s JOIN public.library_entries l ON s.library_entry_id=l.id
   WHERE l.coffee_id=p_record_id OR l.submission_id IN
    (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  SELECT count(*) INTO notes_count FROM public.shot_notes n JOIN public.shots s ON s.id=n.shot_id
   JOIN public.library_entries l ON s.library_entry_id=l.id
   WHERE l.coffee_id=p_record_id OR l.submission_id IN
    (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  SELECT count(*) INTO community_count FROM public.community_shots WHERE coffee_id=p_record_id;
  SELECT count(*) INTO source_count FROM public.coffee_sources WHERE coffee_id=p_record_id;
  SELECT count(*) INTO merged_count FROM public.coffees WHERE merged_into_id=p_record_id;
  SELECT count(*) INTO linked_count FROM private.dic_coffee_first_entry f WHERE f.coffee_id<>p_record_id
   AND f.first_submission_id IN (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
 END IF;
 RETURN jsonb_build_object('kind',p_kind,'record_id',p_record_id,'revision',rev,
  'library_entries',lib_count,'shots',shot_count,'shot_notes',notes_count,
  'community_shots',community_count,'linked_submissions',submissions_count,
  'source_records',source_count,'other_references',linked_count,'merged_coffees',merged_count,
  'blocked',CASE WHEN p_kind='approved' THEN community_count>0 OR merged_count>0 OR linked_count>0
                 WHEN p_kind='submission' THEN linked_count>0 ELSE false END);
END $function$

CREATE OR REPLACE FUNCTION private.dic_admin_delete_record(p_kind text, p_record_id uuid, p_expected_revision bigint, p_expected_impact jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid; actual jsonb; current_revision bigint;
BEGIN
 actor:=private.require_member();
 IF actor IS NULL OR NOT private.is_admin() THEN
  RAISE EXCEPTION USING errcode='42501',message='Administrator required.';
 END IF;
 IF p_record_id IS NULL OR p_expected_revision IS NULL OR
    p_kind IS NULL OR p_kind NOT IN ('shot','submission','approved') OR p_expected_impact IS NULL THEN
  RAISE EXCEPTION USING errcode='22023',message='Invalid delete confirmation.';
 END IF;
 IF p_kind='shot' THEN
  SELECT revision INTO current_revision FROM public.shots WHERE id=p_record_id FOR UPDATE;
 ELSIF p_kind='submission' THEN
  SELECT revision INTO current_revision FROM public.coffee_submissions
   WHERE id=p_record_id AND status IN ('pending','conflict') FOR UPDATE;
 ELSE
  SELECT revision INTO current_revision FROM public.coffees
   WHERE id=p_record_id AND merged_into_id IS NULL FOR UPDATE;
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='40001',message='Record changed or unavailable. Refresh.'; END IF;
 IF current_revision<>p_expected_revision THEN
  RAISE EXCEPTION USING errcode='40001',message='Record revision changed. Refresh before deleting.';
 END IF;
 actual:=private.dic_admin_delete_preview(p_kind,p_record_id);
 IF actual IS DISTINCT FROM p_expected_impact THEN
  RAISE EXCEPTION USING errcode='40001',message='Associated records changed. Review impact again.';
 END IF;
 IF (actual->>'blocked')::boolean THEN
  RAISE EXCEPTION USING errcode='23514',message='Deletion blocked to preserve Community contributions or other canonical references.';
 END IF;
 IF p_kind='shot' THEN
  UPDATE public.recipe_preferences SET favorite_shot_id=NULL,revision=revision+1,updated_at=now()
   WHERE favorite_shot_id=p_record_id;
  DELETE FROM public.shots WHERE id=p_record_id;
 ELSIF p_kind='submission' THEN
  UPDATE public.workspace_state SET current_library_entry_id=NULL,revision=revision+1,updated_at=now()
   WHERE current_library_entry_id IN (SELECT id FROM public.library_entries WHERE submission_id=p_record_id);
  DELETE FROM public.library_entries WHERE submission_id=p_record_id;
  UPDATE private.dic_coffee_audit SET submission_id=NULL WHERE submission_id=p_record_id;
  DELETE FROM private.dic_source_attempts WHERE submission_id=p_record_id;
  DELETE FROM public.coffee_submissions WHERE id=p_record_id AND status IN ('pending','conflict');
 ELSE
  UPDATE public.workspace_state SET current_library_entry_id=NULL,revision=revision+1,updated_at=now()
   WHERE current_library_entry_id IN (SELECT id FROM public.library_entries l
    WHERE l.coffee_id=p_record_id OR l.submission_id IN
     (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id));
  DELETE FROM public.library_entries l WHERE l.coffee_id=p_record_id OR l.submission_id IN
   (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  UPDATE private.dic_coffee_audit SET coffee_id=NULL,submission_id=NULL
   WHERE coffee_id=p_record_id OR submission_id IN
    (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  DELETE FROM private.dic_source_attempts WHERE submission_id IN
   (SELECT id FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id);
  DELETE FROM private.dic_coffee_first_entry WHERE coffee_id=p_record_id;
  DELETE FROM public.coffee_submissions WHERE canonical_coffee_id=p_record_id;
  DELETE FROM public.coffee_sources WHERE coffee_id=p_record_id;
  DELETE FROM private.dic_coffee_aliases WHERE coffee_id=p_record_id;
  DELETE FROM public.recipe_families WHERE coffee_id=p_record_id;
  DELETE FROM public.coffees WHERE id=p_record_id;
 END IF;
 INSERT INTO private.dic_admin_delete_receipts(actor_id,record_kind,record_id,impact)
  VALUES(actor,p_kind,p_record_id,actual);
 RETURN jsonb_build_object('ok',true,'deleted_kind',p_kind,'impact',actual);
END $function$
